"""「使用上次舰队」选船页的确定键；原 (873/960, 500/540) 偏下，已上移。"""


def _is_overview_or_main(screen: np.ndarray) -> bool:
    """暂离后的可接受落点：决战总览页或主页面。"""
    from autowsgr.ui.main_page import MainPage

    return bool(
        DecisiveBattlePage.is_current_page(screen).matched
        or MainPage.is_current_page(screen).matched
    )


class SortieOutcome(enum.Enum):
    """点“出征”后的立即结果。"""

    BATTLE = 'battle'
    """已切入战斗 UI。"""

    DAMAGE_CONFIRM = 'damage_confirm'
    """非旗舰大破确认框，需要取消后修船。"""

    FLAGSHIP_SEVERE = 'flagship_severe'
    """旗舰大破短条/2 秒后仍在地图，需要修船。"""

    STILL_MAP = 'still_map'
    """超时仍在地图但未识别到短条。"""


class DecisiveMapController:
    """决战地图页控制器。

    Parameters
    ----------
    ctrl:
        Android 设备控制器。
    config:
        决战配置。
    ocr:
        OCR 引擎。
    image_matcher:
        图像匹配函数 (可选)。
    """

    def __init__(
        self,
        ctx: GameContext,
        config: DecisiveConfig,
    ) -> None:
        self._ctx = ctx
        self._ctrl = ctx.ctrl
        self._config = config
        self._ocr = ctx.ocr

    # ══════════════════════════════════════════════════════════════════════
    # 页面状态检测
    # ══════════════════════════════════════════════════════════════════════

    def screenshot(self) -> np.ndarray:
        """获取当前截图。"""
        return self._ctrl.screenshot()

    def _page_drift(self, *, source: str, target: str, action: str) -> PageDriftError:
        """把决战步骤的到达超时统一包装成可恢复的 ``PageDriftError``。"""
        return PageDriftError(
            f'决战步骤未到达: {source} -> {target}',
            target=target,
            page_trail=[source, target],
            action_trail=[action],
            screen=self._ctrl.screenshot(),
        )

    def detect_overlay(self, screen: np.ndarray | None = None) -> DecisiveOverlay | None:
        """检测当前地图页上的 overlay 类型。"""
        if screen is None:
            screen = self._ctrl.screenshot()
        return detect_decisive_overlay(screen)

    def is_map_page(self, screen: np.ndarray | None = None) -> bool:
        """判断截图是否为决战地图页 (无 overlay 遮挡)。"""
        if screen is None:
            screen = self._ctrl.screenshot()
        return is_decisive_map_page(screen)

    def detect_decisive_phase(  # noqa: PLR0911
        self,
        screen: np.ndarray | None = None,
    ) -> DecisivePhase | None:
        """单次截图检测当前决战页面状态。

        按以下优先级检测::

            1. dock_full      — 弹窗存活时间极短 (~2s)
            2. use_last_fleet — 进入已有进度章节时弹出
            3. overlay        — 战备舰队 / 前进点（必须先于地图页判断）
            4. 地图页         — 无 overlay 的正常决战地图页

        Returns
        -------
        DecisivePhase | None
            检测到的阶段；过场动画中等未知状态返回 ``None``。
        """
        from autowsgr.image_resources import Templates

        if screen is None:
            screen = self._ctrl.screenshot()

        if ImageChecker.template_exists(
            screen,
            Templates.Build.SHIP_FULL_DEPOT,
            confidence=0.8,
        ):
            _log.warning('[地图控制器] 检测到船坞已满弹窗')
            return DecisivePhase.DOCK_FULL

        if ImageChecker.template_exists(
            screen,
            Templates.Decisive.USE_LAST_FLEET,
            confidence=0.8,
        ):
            _log.info('[地图控制器] 检测到「使用上次舰队」按钮')
            return DecisivePhase.USE_LAST_FLEET

        overlay = detect_decisive_overlay(screen)
        if overlay is not None:
            if overlay == DecisiveOverlay.ADVANCE_CHOICE:
                return DecisivePhase.ADVANCE_CHOICE
            if overlay == DecisiveOverlay.FLEET_ACQUISITION:
                return DecisivePhase.CHOOSE_FLEET

        if is_decisive_map_page(screen):
            # 进图后的首个稳定帧有时会短暂满足“地图页”特征，但战备舰队
            # overlay 会在随后 1-2 帧内出现。这里等画面连续稳定两帧再复检，
            # 只把稳定后仍是地图页的结果视为 PREPARE_COMBAT。
            confirm_screen = wait_for_stable_screen(
                self._ctrl,
                timeout=0.8,
                interval=0.12,
                stable_frames=2,
                source='决战地图页复检',
                stop_event=self._ctx.stop_event,
            )

            overlay = detect_decisive_overlay(confirm_screen)
            if overlay is not None:
                if overlay == DecisiveOverlay.ADVANCE_CHOICE:
                    _log.debug('[地图控制器] 地图页复检修正为 overlay: advance_choice')
                    return DecisivePhase.ADVANCE_CHOICE
                if overlay == DecisiveOverlay.FLEET_ACQUISITION:
                    _log.debug('[地图控制器] 地图页复检修正为 overlay: fleet_acquisition')
                    return DecisivePhase.CHOOSE_FLEET

            if is_decisive_map_page(confirm_screen):
                return DecisivePhase.PREPARE_COMBAT

        return None

    # ── 舰船图标颜色检测参数 (HSV, BGR 输入) ──────────────────────
    # 决战地图上的舰船指示器呈橙黄色高亮，是该色段面积最大的连通区域
    _SHIP_HSV_LO = np.array([18, 100, 200], dtype=np.uint8)
    _SHIP_HSV_HI = np.array([32, 180, 255], dtype=np.uint8)
    _SHIP_MIN_AREA = 500  # 真实舰标面积远大于地图杂色 (通常 >2000)

    @staticmethod
    def _locate_ship_icon(bgr: np.ndarray) -> float | None:
        """通过 HSV 颜色分割定位舰船指示器的 **相对** X 中心。

        不依赖任何图像模板，仅利用舰船指示器在决战地图上独特的
        橙黄色高亮面积远大于其它同色碎片这一视觉特征。

        Returns
        -------
        float | None
            舰标中心 X 占图像宽度比例 (0-1)；检测失败返回 ``None``。
        """
        hsv = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)
        mask = cv2.inRange(
            hsv, DecisiveMapController._SHIP_HSV_LO, DecisiveMapController._SHIP_HSV_HI
        )
        # 闭运算连接临近像素
        kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (5, 3))
        mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel)

        n_labels, _labels, stats, centroids = cv2.connectedComponentsWithStats(mask)
        if n_labels < 2:
            return None

        # 跳过背景 (label 0)，取面积最大的连通区域
        areas = stats[1:, cv2.CC_STAT_AREA]
        best = int(areas.argmax()) + 1
        if stats[best, cv2.CC_STAT_AREA] < DecisiveMapController._SHIP_MIN_AREA:
            return None
        return float(centroids[best][0]) / bgr.shape[1]

    def dll_recognize_map(self, dll: ApiDll, screen: np.ndarray, center: float) -> str:
        h, w = screen.shape[:2]
        x1 = max(0, int((center - 0.03) * w))
        x2 = min(w, int((center - 0.03 + 0.042) * w))
        col_crop = screen[0:h, x1:x2]
        result = dll.recognize_map(col_crop)
        # save_image(col_crop, result + '.png')
        return result

    def get_ship_icon_pos(self) -> float | None:
        detect_screen = self._ctrl.screenshot()
        # 针对Ex5特调，A节点不选择分支，直接进入战备舰队获取
        screen_is_fleet_acquisition = is_fleet_acquisition(detect_screen)
        if screen_is_fleet_acquisition:
            return -1
        # _locate_ship_icon 需要 BGR；screenshot() 返回 RGB
        bgr = cv2.cvtColor(detect_screen, cv2.COLOR_RGB2BGR)
        icon_rel_x = self._locate_ship_icon(bgr)
        return icon_rel_x

    def get_ship_icon_pos_with_retry(self) -> float | None:
        _icon_timeout = 10.0
        _icon_gap = 0.15
        deadline = time.monotonic() + _icon_timeout
        icon_rel_x: float | None = None
        while time.monotonic() < deadline:
            icon_rel_x = self.get_ship_icon_pos()
            if icon_rel_x is not None:
                break
            if self._ctx.stop_event.wait(_icon_gap):
                raise TaskStopRequested('决战节点图标定位')
        return icon_rel_x

    def recognize_node(
        self,
    ) -> str:
        """DLL 识别当前决战节点字母 (如 ``'A'``, ``'B'``)。

        算法 (无模板依赖):

        1. 轮询截图，通过 **HSV 颜色分割** 定位舰船指示器 X 坐标
           (地图上最大的橙黄色连通区域)。
        2. 以舰标 X 为参考裁剪全高竖列，送 DLL ``recognize_map`` 识别。
        3. DLL 返回 ``'0'`` 时重试 (最多 3 次)，全部失败抛出异常。
        """
        _max_retry = 3
        dll = get_api_dll()

        for retry in range(_max_retry + 1):
            icon_rel_x: float | None = self.get_ship_icon_pos_with_retry()
            for retry_icon in range(_max_retry + 1):
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=0.5,
                    interval=0.1,
                    stable_frames=2,
                    source='决战节点图标',
                    stop_event=self._ctx.stop_event,
                )
                icon_rel_x_now = self.get_ship_icon_pos_with_retry()
                if icon_rel_x_now == -1:
                    return 'CHOOSE_FLEET'
                if icon_rel_x_now == icon_rel_x:
                    _log.debug('[地图控制器] 舰船指示器位置: X={:.5f}', icon_rel_x)
                    break
                _log.debug(
                    '[地图控制器] 舰船指示器位置偏移, 重试{:d}: X1={:.5f}, X2={:.5f}',
                    retry_icon,
                    icon_rel_x,
                    icon_rel_x_now,
                )
                icon_rel_x = icon_rel_x_now

            if icon_rel_x is None:
                raise RuntimeError('决战节点识别失败: 舰船指示器超时未出现')

            # 2. 取新截图，按舰标 X 裁剪竖列
            fresh_screen = self._ctrl.screenshot()

            # 3. DLL 识别
            try:
                result = self.dll_recognize_map(dll, fresh_screen, icon_rel_x)
                if result != '0':
                    _log.info('[地图控制器] 识别决战节点: {}', result[0])
                    return result[0]
            except Exception:
                _log.warning('[地图控制器] DLL 节点识别异常', exc_info=True)

            if retry >= _max_retry:
                break
            _log.warning(
                '[地图控制器] 节点识别失败, 正在重试第 {} 次',
                retry + 1,
            )

        raise RuntimeError(f'决战节点识别失败: 重试 {_max_retry + 1} 次后仍无法识别')

    # ══════════════════════════════════════════════════════════════════════
    # 战备舰队获取 overlay
    # ══════════════════════════════════════════════════════════════════════

    def recognize_fleet_options(
        self,
        screen: np.ndarray | None = None,
        fallback_score: int | None = None,
        *,
        score_status: list[bool] | None = None,
    ) -> tuple[int, dict[str, FleetSelection]]:
        """OCR 识别战备舰队获取界面的可选项。"""
        if screen is None:
            screen = self.wait_for_fleet_overlay_stable()
        return _fleet_ocr.recognize_fleet_options(
            self._ocr,
            screen,
            fallback_score=fallback_score,
            score_status=score_status,
        )

    def wait_for_fleet_overlay_stable(
        self,
        screen: np.ndarray | None = None,
        timeout: float = 8.0,
    ) -> np.ndarray:
        """等待战备舰队弹窗稳定后返回截图。

        当上层已通过阶段纠偏进入 ``CHOOSE_FLEET`` 时，当前截图本身就可能是
        首进购买界面，此时不要再次强依赖旧的 overlay 像素签名；直接以当前截图
        为起点做短暂稳定等待即可。
        """
        if screen is None:
            screen = self.wait_for_overlay(DecisiveOverlay.FLEET_ACQUISITION, timeout=timeout)

        # 以帧差确认弹窗内容（卡片/按钮）已经不再变化，而不是固定等 1s。
        return wait_for_stable_screen(
            self._ctrl,
            timeout=1.0,
            interval=0.15,
            stable_frames=2,
            source='战备舰队弹窗稳定',
            stop_event=self._ctx.stop_event,
        )

    def is_purchase_confirm_visible(self, screen: np.ndarray | None = None) -> bool:
        """购买页右下角是否为黄色「确定」（即已选中至少一张卡）。"""
        if screen is None:
            screen = self._ctrl.screenshot()
        pixel = PixelChecker.get_pixel(screen, *PURCHASE_CONFIRM_PROBE)
        yellow = Color.of(*PURCHASE_CONFIRM_YELLOW)
        red = Color.of(*PURCHASE_CLOSE_RED)
        if pixel.near(yellow, PURCHASE_COLOR_TOLERANCE):
            return True
        if pixel.near(red, PURCHASE_COLOR_TOLERANCE):
            return False
        # 颜色漂移时用“偏黄”启发式：R/G 高、B 低。
        return pixel.r > 170 and pixel.g > 140 and pixel.b < 120

    def select_fleet_offer(
        self,
        click_position: tuple[float, float],
        *,
        timeout: float = 1.0,
    ) -> bool:
        """点选一张卡，并等卡片选中态生效。"""
        self._ctrl.click(*click_position)
        # 多选时第一张之后“确定”按钮已经是黄色，不能再用它判断
        # 后续卡片是否被点中；统一等一帧稳定，避免连点吞掉选中事件。
        wait_for_stable_screen(
            self._ctrl,
            timeout=0.35,
            interval=0.08,
            stable_frames=2,
            source='决战点选购买卡',
            stop_event=self._ctx.stop_event,
        )
        if self.is_purchase_confirm_visible():
            return True
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if self._ctx.stop_event.wait(0.08):
                raise TaskStopRequested('决战点选购买卡')
            if self.is_purchase_confirm_visible():
                return True
        _log.warning('[地图控制器] 点选购买卡后未检测到黄色确定按钮')
        return False

    def confirm_fleet_purchase(self, *, timeout: float = 5.0) -> bool:
        """点击黄色「确定」并等待购买页关闭。"""
        self._ctrl.click(*CLICK_FLEET_CONFIRM)
        return self._wait_leave_fleet_overlay(timeout=timeout)

    def buy_fleet_offers(
        self,
        names: list[str],
        selections: dict[str, FleetSelection],
    ) -> list[str]:
        """按顺序点选多个目标，然后一次确定。

        Returns
        -------
        list[str]
            实际点选并确认成功的名称；空列表表示失败。
        """
        selected: list[str] = []
        for name in names:
            selection = selections.get(name)
            if selection is None:
                _log.warning('[地图控制器] 购买目标不在 OCR 结果中: {}', name)
                continue
            if self.select_fleet_offer(selection.click_position):
                selected.append(name)
        if not selected:
            _log.warning('[地图控制器] 没有成功点选任何购买目标')
            return []
        if not self.confirm_fleet_purchase():
            return []
        return selected

    def buy_first_offer_and_confirm(self) -> bool:
        """购买页无目标/无关闭按钮时，点最左第一张卡并确定破局。"""
        return self.select_fleet_offer(
            (FLEET_CARD_X_POSITIONS[0], FLEET_CARD_CLICK_Y)
        ) and self.confirm_fleet_purchase()

    def _wait_leave_fleet_overlay(self, *, timeout: float = 5.0) -> bool:
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            screen = self._ctrl.screenshot()
            if not is_fleet_acquisition(screen):
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=0.5,
                    interval=0.1,
                    stable_frames=2,
                    source='离开战备舰队弹窗',
                    stop_event=self._ctx.stop_event,
                )
                return True
            if self._ctx.stop_event.wait(0.15):
                raise TaskStopRequested('决战购买页关闭')
        _log.warning('[地图控制器] 战备舰队弹窗超时未关闭')
        return False

    def buy_fleet_option(self, click_position: tuple[float, float]) -> None:
        """兼容旧调用点：点选一张卡（不点确定）。"""
        self.select_fleet_offer(click_position)

    def refresh_fleet(self) -> None:
        """点击「刷新」按钮，刷新备选舰船。"""
        self._ctrl.click(*CLICK_FLEET_REFRESH)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.5,
            interval=0.15,
            stable_frames=2,
            source='决战刷新舰队',
            stop_event=self._ctx.stop_event,
        )

    def close_fleet_overlay(self) -> bool:
        """关闭战备舰队获取 overlay（红色「关闭」），并确认已离开。"""
        self._ctrl.click(*CLICK_FLEET_CLOSE)
        return self._wait_leave_fleet_overlay(timeout=5.0)

    def is_fleet_overlay_open(self) -> bool:
        """当前是否仍停留在战备舰队获取界面。"""
        return is_fleet_acquisition(self._ctrl.screenshot())

    def check_dock_full(self) -> bool:
        """检查当前界面是否出现船坞已满提示。"""
        from autowsgr.image_resources import Templates

        screen = self._ctrl.screenshot()
        return ImageChecker.template_exists(
            screen,
            Templates.Build.SHIP_FULL_DEPOT,
            confidence=0.8,
        )

    def use_last_fleet(self, timeout: float = 8.0) -> bool:
        """点击「使用上次舰队」→ 确定，并轮询到选船页消失。

        对应 Legacy ``decisive_battle_image[7]`` + ``click(873, 500)``。模板
        实测命中约 0.97，这里点模板中心而不是硬编码按钮坐标；确认键由
        ``(873/960, 500/540)`` 上移到 ``(0.906, 0.899)``。

        Returns
        -------
        bool
            选船页在 ``timeout`` 内消失返回 ``True``；模板未出现、点击后
            仍停留在选船页或超时返回 ``False``，由调用方决定重试或报错。
        """
        from autowsgr.image_resources import Templates

        # 进入本方法前状态机已识别到选船页；最多再等 2s 以容忍过场动画，
        # 避免一帧未命中就立刻判失败。
        find_window = min(2.0, timeout)
        find_deadline = time.monotonic() + find_window
        match = None
        while time.monotonic() < find_deadline:
            match = ImageChecker.find_template(
                self._ctrl.screenshot(),
                Templates.Decisive.USE_LAST_FLEET,
                confidence=0.85,
            )
            if match is not None:
                break
            if self._ctx.stop_event.wait(0.2):
                raise TaskStopRequested('决战使用上次舰队')

        if match is None:
            _log.warning('[地图控制器] 使用上次舰队：{:.1f}s 内未找到按钮模板', find_window)
            return False

        _log.info(
            '[地图控制器] 使用上次舰队：点击模板中心 ({:.3f}, {:.3f})',
            *match.center,
        )
        self._ctrl.click(*match.center)
        wait_for_stable_screen(
            self._ctrl,
            timeout=0.8,
            interval=0.1,
            stable_frames=2,
            source='使用上次舰队-按钮',
            stop_event=self._ctx.stop_event,
        )
        self._ctrl.click(*CLICK_USE_LAST_FLEET_CONFIRM)

        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if not is_fleet_select_page(self._ctrl.screenshot()):
                _log.info('[地图控制器] 使用上次舰队：选船页已退出')
                return True
            if self._ctx.stop_event.wait(0.2):
                raise TaskStopRequested('决战使用上次舰队确认')

        _log.warning(
            '[地图控制器] 使用上次舰队：点击后 {:.1f}s 仍停留在选船页',
            timeout,
        )
        return False

