    def drain_insufficient_popup(self) -> bool:
        """检测并关闭「点数不足」弹窗；未出现返回 False。

        只在余额可疑（点击后未下降）时调用，避免每次连点都做 OCR。
        """
        screen = self._ctrl.screenshot()
        detail = ImageChecker.find_any(screen, Templates.Confirm.all(), confidence=0.85)
        if detail is None:
            # 没有确认按钮就不是“点数不足”弹窗，避免每次连点都做 OCR。
            return False
        roi = ROI(x1=0.25, y1=0.30, x2=0.75, y2=0.65)
        text = self._ocr.recognize_single(roi.crop(screen)).text
        if '不足' not in text and '点数' not in text:
            return False
        self._ctrl.click(*detail.center)
        wait_for_stable_screen(
            self._ctrl,
            timeout=0.6,
            interval=0.1,
            stable_frames=2,
            source='关闭点数不足弹窗',
            stop_event=self._ctx.stop_event,
        )
        return True

    def check_fleet(self) -> list[str | None]:
        """恢复进度时只读取当前编队，不扫描船坞/不读血量。

        扫描船坞会把“玩家拥有但本局未购买”的船误当成决战已有舰船，
        因此恢复模式只信任准备页上的当前编队。
        """
        _log.info('[地图控制器] 扫描当前编队')
        page = self.enter_formation()
        if page is None:
            _log.info('[地图控制器] 扫描编队被 overlay 打断，保留现有状态')
            return []
        fleet = page.detect_fleet(self._ctrl.screenshot())
        page.go_back()
        _log.info('[地图控制器] 当前编队: {}', fleet)
        return fleet

