    # 选择前进点 overlay
    # ══════════════════════════════════════════════════════════════════════

    def select_advance_card(self, index: int) -> None:
        """选择前进点卡片并确认，验证 overlay 已离开。

        6-1 是两卡布局、6-2 是三卡布局，固定坐标会点进卡片间隙。
        这里优先用 OCR 识别 A1/A2/A3 标签定位，失败再依次尝试
        三卡/两卡固定坐标。
        """
        screen = self._ctrl.screenshot()
        detected = self._advance_card_positions_from_ocr(screen)
        candidates: list[list[tuple[float, float]]] = []
        for positions in (detected, ADVANCE_CARD_POSITIONS, ADVANCE_CARD_POSITIONS_2):
            if positions and len(positions) > index and positions not in candidates:
                candidates.append(positions)

        last_exc: NavigationError | None = None
        for positions in candidates:
            self._ctrl.click(*positions[index])
            wait_for_stable_screen(
                self._ctrl,
                timeout=0.6,
                interval=0.1,
                stable_frames=2,
                source='前进点卡片选择',
                stop_event=self._ctx.stop_event,
            )
            try:
                click_and_wait_for_page(
                    self._ctrl,
                    CLICK_ADVANCE_CONFIRM,
                    lambda current: detect_decisive_overlay(current)
                    != DecisiveOverlay.ADVANCE_CHOICE
                    and (
                        is_decisive_map_page(current)
                        or detect_decisive_overlay(current) is not None
                    ),
                    config=NavConfig(
                        timeout=5.0,
                        interval=0.3,
                        max_retries=2,
                        stable_frames=2,
                    ),
                    source='决战-前进点',
                    target='决战地图/下一 overlay',
                    stop_event=self._ctx.stop_event,
                )
                return
            except NavigationError as exc:
                last_exc = exc
                _log.warning('[地图控制器] 前进点确认未生效，尝试下一种卡片布局')

        raise self._page_drift(
            source='决战-前进点',
            target='决战地图/下一 overlay',
            action='select_advance_card',
        ) from last_exc

    def _advance_card_positions_from_ocr(
        self,
        screen: np.ndarray,
    ) -> list[tuple[float, float]]:
        """用 A1/A2/A3 标签 OCR 定位前进点卡片中心。"""
        try:
            results = self._ocr.recognize(
                screen,
                allowlist='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
            )
        except Exception:  # noqa: BLE001 - OCR 失败时退回固定坐标
            return []

        height, width = screen.shape[:2]
        points: list[tuple[float, float]] = []
        for item in results:
            text = item.text.strip().upper()
            if not re.fullmatch(r'[A-J]\d', text):
                continue
            bbox = item.bbox
            if bbox is None:
                continue
            x1, y1, x2, y2 = bbox
            cx = (x1 + x2) / 2 / width
            cy = (y1 + y2) / 2 / height
            if 0.25 <= cy <= 0.45 and 0.05 <= cx <= 0.95:
                # 标签在卡片左上角，往右下偏移到卡片内部。
                points.append((min(0.95, cx + 0.025), min(0.75, cy + 0.07)))

        points.sort()
        unique: list[tuple[float, float]] = []
        for point in points:
            if not unique or abs(point[0] - unique[-1][0]) > 0.10:
                unique.append(point)
        if unique:
            _log.info('[地图控制器] 前进点卡片 OCR 定位: {}', unique)
        return unique

