    def enter_formation(self) -> DecisiveBattlePreparationPage | None:
        """点击右下角「编队」按钮，返回准备页控制器。

        如果点击前后弹出了战备舰队获取 overlay，返回 ``None``，由状态机
        重新进入 ``CHOOSE_FLEET``；绝不在地图按钮上盲点直到超时。
        """
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.5,
            interval=0.15,
            stable_frames=2,
            source='决战地图-编队前',
            stop_event=self._ctx.stop_event,
        )
        screen = self._ctrl.screenshot()
        if detect_decisive_overlay(screen) is not None:
            _log.info('[地图控制器] 编队前出现 overlay，放弃点击编队')
            return None

        click_and_wait_for_page(
            self._ctrl,
            CLICK_FORMATION,
            lambda current: BattlePreparationPage.is_current_page(current)
            or detect_decisive_overlay(current) is not None,
            config=NavConfig(timeout=10.0, interval=0.5, max_retries=3),
            source='决战地图',
            target='出征准备/overlay',
            stop_event=self._ctx.stop_event,
        )
        screen = self._ctrl.screenshot()
        if detect_decisive_overlay(screen) is not None:
            _log.info('[地图控制器] 编队过程中出现 overlay，交给状态机处理')
            return None
        return DecisiveBattlePreparationPage(self._ctx, self._config, self._ocr)

    def is_battle_ui(self, screen: np.ndarray | None = None) -> bool:
        """截图是否为战斗界面（战况/阵型/战斗/夜战任一）。"""
        if screen is None:
            screen = self._ctrl.screenshot()
        for template in (
            CombatTemplates.FIGHT_PERIOD,
            CombatTemplates.FIGHT_CONDITION,
            CombatTemplates.FORMATION,
            CombatTemplates.NIGHT_BATTLE,
        ):
            if ImageChecker.template_exists(screen, template, confidence=0.8):
                return True
        return False

    def cancel_damage_confirm(self) -> None:
        """点击非旗舰大破确认框的「取消」。"""
        self._ctrl.click(*CLICK_DAMAGE_CANCEL)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.0,
            interval=0.12,
            stable_frames=2,
            source='取消大破出征确认',
            stop_event=self._ctx.stop_event,
        )

    def wait_for_start_outcome(self, *, timeout: float | None = None) -> SortieOutcome:
        """轮询“出征/开始出征”后的立即结果。

        地图页「出征」和准备页「开始出征」共用同一套判断。
        """
        timeout = self._config.sortie_battle_timeout if timeout is None else timeout
        deadline = time.monotonic() + timeout
        while True:
            screen = self._ctrl.screenshot()
            if is_damage_confirm(screen):
                return SortieOutcome.DAMAGE_CONFIRM
            if is_flagship_severe(screen):
                return SortieOutcome.FLAGSHIP_SEVERE
            if self.is_battle_ui(screen):
                return SortieOutcome.BATTLE
            if time.monotonic() >= deadline:
                return SortieOutcome.STILL_MAP
            if self._ctx.stop_event.wait(0.12):
                raise TaskStopRequested('决战等待出征结果')

    def click_sortie_and_probe(self, *, timeout: float | None = None) -> SortieOutcome:
        """点地图页「出征」并轮询判断：进战斗 / 大破确认 / 旗舰短条 / 仍在地图。"""
        self._ctrl.click(*CLICK_SORTIE)
        return self.wait_for_start_outcome(timeout=timeout)

    def finish_battle_to_map(self, *, timeout: float | None = None) -> DecisivePhase:
        """战斗结束后连点结算页，直到回到地图/overlay。

        不读血量、不采集评级、不等待固定动画；每 0.2 秒一轮截图 + 点击。
        """
        from autowsgr.combat.actions import click_result

        timeout = self._config.finish_battle_timeout if timeout is None else timeout
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            screen = self._ctrl.screenshot()
            phase = self.detect_decisive_phase(screen)
            if phase is not None:
                _log.info('[地图控制器] 结算页已回到: {}', phase.name)
                return phase

            # 小关通关/奖励页常见蓝色确认按钮；找不到就点右下角继续。
            detail = ImageChecker.find_any(
                screen,
                Templates.Confirm.all(),
                confidence=0.88,
            )
            if detail is not None:
                self._ctrl.click(*detail.center)
            else:
                click_result(self._ctrl)

            if self._ctx.stop_event.wait(0.2):
                raise TaskStopRequested('决战结算连点')

        raise PageDriftError(
            f'战斗结束后 {timeout:.0f}s 未回到决战地图',
            target='决战地图',
            page_trail=['战斗结算'],
            action_trail=['finish_battle_to_map'],
            screen=self._ctrl.screenshot(),
        )

    def finish_stage_clear(self, *, timeout: float = 20.0) -> None:
        """小关通关后快速点过结算/奖励页，直到回到决战总览。"""
        from autowsgr.combat.actions import click_result

        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            screen = self._ctrl.screenshot()
            if DecisiveBattlePage.is_current_page(screen).matched:
                _log.info('[地图控制器] 小关通关，已回到决战总览')
                return
            detail = ImageChecker.find_any(
                screen,
                Templates.Confirm.all(),
                confidence=0.88,
            )
            if detail is not None:
                self._ctrl.click(*detail.center)
            else:
                click_result(self._ctrl)
            if self._ctx.stop_event.wait(0.2):
                raise TaskStopRequested('决战小关结算')
        raise PageDriftError(
            '小关通关后未回到决战总览',
            target='决战总览',
            page_trail=['小关结算'],
            action_trail=['finish_stage_clear'],
            screen=self._ctrl.screenshot(),
        )

    def go_to_map_page(self) -> None:
        """确保当前在决战地图页（若在准备页则点击左上角返回）。"""
        screen = self._ctrl.screenshot()
        if is_decisive_map_page(screen):
            return
        try:
            click_and_wait_for_page(
                self._ctrl,
                (0.03, 0.06),
                is_decisive_map_page,
                config=NavConfig(
                    max_retries=1,
                    timeout=2.5,
                    interval=0.3,
                    stable_frames=2,
                ),
                source='决战准备页',
                target='决战地图页',
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[地图控制器] 无法确认已回到地图页')

